  Ciphertext t4 = w2 + w2 - one;
  Ciphertext c6w = w * c6;
  Ciphertext q = c6w + c6w + c4;
  Ciphertext p = t4 * q;
  Ciphertext term2 = w * c2;
  Ciphertext term1 = z * c1;
  Ciphertext r = term2 - c6w;
  r = r + term1;
  Ciphertext result = p + r;
  result = result + c0;
